contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Ensure we never create credit for this contract: no deposits from this contract are made.
    // Parameter kept only to satisfy the requirement of having parameters; it's unused.
    function run(uint unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Do not require any specific address(this).balance to avoid failing in environments like Foundry.

        // Observe balances before call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Call withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: since this contract did not deposit, its credit should be zero; therefore withdrawAll
        // must either revert or be a no-op w.r.t. Ether balances observable externally.
        assert(reverted || (afterC == beforeC && afterThis == beforeThis));
    }

    receive() external payable {}
}

